import java.util.Scanner;
class TemperatureChecker {
    void checkTemperature(double temperature) {
        if (temperature < 0) {
            System.out.println("Freezing");
        } else if (temperature <= 20) {
            System.out.println("Cold");
        } else if (temperature <= 30) {
            System.out.println("Warm");
        } else {
            System.out.println("Hot");
        }
    }
}
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        double temperature = scanner.nextDouble();
        TemperatureChecker checker = new TemperatureChecker();
        checker.checkTemperature(temperature);
        scanner.close();
    }
}

import java.util.Scanner;
class DivisibilityChecker {
    void checkDivisibility(int number) {
        if (number % 3 == 0 && number % 5 == 0) {
            System.out.println("Divisible by both");
        } else if (number % 3 == 0) {
            System.out.println("Divisible by 3");
        } else if (number % 5 == 0) {
            System.out.println("Divisible by 5");
        } else {
            System.out.println("Not divisible");
        }
    }
}
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int number = scanner.nextInt();
        DivisibilityChecker checker = new DivisibilityChecker();
        checker.checkDivisibility(number);
        scanner.close();
    }
}

import java.util.Scanner;
class ProfitLoss {
    void calculate(double costPrice, double sellingPrice) {
        if (costPrice < 0 || sellingPrice < 0) {
            System.out.println("Invalid input");
        } else if (sellingPrice > costPrice) {
            System.out.printf("Profit %.2f%n", sellingPrice - costPrice);
        } else if (costPrice > sellingPrice) {
            System.out.printf("Loss %.2f%n", costPrice - sellingPrice);
        } else {
            System.out.println("No profit no loss");
        }
    }
}
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        double costPrice = scanner.nextDouble();
        double sellingPrice = scanner.nextDouble();

        ProfitLoss result = new ProfitLoss();
        result.calculate(costPrice, sellingPrice);
        scanner.close();
    }
}

import java.util.Scanner;
class AttendanceChecker {
    void checkEligibility(int classesHeld, int classesAttended) {
        if (classesHeld <= 0 || classesAttended < 0 || classesAttended > classesHeld) {
            System.out.println("Invalid input");
        } else if (classesAttended * 100.0 / classesHeld >= 75) {
            double percentage = classesAttended * 100.0 / classesHeld;
            System.out.printf("Allowed %.2f%n", percentage);
        } else {
            double percentage = classesAttended * 100.0 / classesHeld;
            System.out.printf("Not allowed %.2f%n", percentage);
        }
    }
}
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int classesHeld = scanner.nextInt();
        int classesAttended = scanner.nextInt();
        AttendanceChecker checker = new AttendanceChecker();
        checker.checkEligibility(classesHeld, classesAttended);
        scanner.close();
    }
}

import java.util.Scanner;
class UnitConverter {
    void convert(int choice, double value) {
        switch (choice) {
            case 1:
                System.out.printf("%.2f%n", (value * 9 / 5) + 32);
                break;
            case 2:
                System.out.printf("%.2f%n", value * 0.621371);
                break;
            case 3:
                System.out.printf("%.2f%n", value * 2.20462);
                break;
            default:
                System.out.println("Invalid choice");
        }
    }
}
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int choice = scanner.nextInt();
        double value = scanner.nextDouble();
        UnitConverter converter = new UnitConverter();
        converter.convert(choice, value);
        scanner.close();
    }
}

